package in.gridcare.portal.web;
import in.gridcare.portal.model.*;import in.gridcare.portal.repo.CustomerRepository;import in.gridcare.portal.service.*;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@RestController @RequestMapping("/api")
public class ApiController{
private final PortalService service;private final OtpService otp;private final CustomerRepository customers;
@Value("${app.demo-otp-response:true}") private boolean demoOtp;
private final Map<String,Session> sessions=new ConcurrentHashMap<>();
private static final String ADMIN_ID="ADMIN001",ADMIN_PASSWORD="Admin@123";
public ApiController(PortalService s,OtpService o,CustomerRepository c){service=s;otp=o;customers=c;}
@PostMapping("/auth/otp/request") public Map<String,Object> request(@Valid @RequestBody OtpRequest r){service.verifyCustomer(r.customerId(),r.mobile());String id=UUID.randomUUID().toString(),code=otp.issue(id,r.customerId());System.out.println("[DEMO OTP] "+r.customerId()+" -> "+code+" (disable OTP logging in production)");Map<String,Object> out=new LinkedHashMap<>();out.put("requestId",id);out.put("message","OTP generated. It expires in 5 minutes.");if(demoOtp)out.put("demoOtp",code);return out;}
@PostMapping("/auth/otp/verify") public Map<String,Object> verify(@Valid @RequestBody OtpVerify r){Customer c=service.verifyCustomer(r.customerId(),r.mobile());otp.verify(r.requestId(),r.customerId(),r.otp());String token=UUID.randomUUID().toString();sessions.put(token,new Session("consumer",c.getCustomerId()));return Map.of("token",token,"role","consumer","customer",customerDto(c));}
@PostMapping("/auth/admin") public Map<String,Object> admin(@Valid @RequestBody AdminLogin r){if(!ADMIN_ID.equals(r.adminId())||!ADMIN_PASSWORD.equals(r.password()))throw PortalException.unauthorized("Invalid admin ID or password.");String token=UUID.randomUUID().toString();sessions.put(token,new Session("admin",ADMIN_ID));return Map.of("token",token,"role","admin","admin",Map.of("adminId",ADMIN_ID,"name","GridCare Administrator"));}
@GetMapping("/consumer/profile") public Map<String,Object> profile(@RequestHeader(value="Authorization",required=false) String h){Session s=require(h,"consumer");return customerDto(customers.findByCustomerId(s.subject).orElseThrow(()->PortalException.missing("Customer not found.")));}
@GetMapping("/consumer/bills") public List<Map<String,Object>> myBills(@RequestHeader(value="Authorization",required=false) String h){return service.customerBills(require(h,"consumer").subject).stream().map(this::billDto).toList();}
@GetMapping("/consumer/bills/{id}") public Map<String,Object> myBill(@RequestHeader(value="Authorization",required=false) String h,@PathVariable Long id){return billDto(service.customerBill(require(h,"consumer").subject,id));}
@PostMapping("/consumer/bills/{id}/pay") public Map<String,Object> pay(@RequestHeader(value="Authorization",required=false) String h,@PathVariable Long id,@RequestBody(required=false) PayRequest r){PaymentRecord p=service.pay(require(h,"consumer").subject,id,r==null?"DEMO":r.method());return Map.of("paymentReference",p.getPaymentReference(),"amount",p.getAmount(),"method",p.getMethod(),"paidAt",p.getPaidAt().toString());}
@PostMapping("/admin/customers") public Map<String,Object> addCustomer(@RequestHeader(value="Authorization",required=false) String h,@Valid @RequestBody NewCustomer r){require(h,"admin");if(customers.findByCustomerId(r.customerId()).isPresent())throw PortalException.conflict("Customer ID already exists.");if(customers.findAll().stream().anyMatch(c->c.getMobile().equals(r.mobile())))throw PortalException.conflict("Mobile number already exists.");return customerDto(customers.save(new Customer(r.customerId(),r.name(),r.mobile(),r.tariffType())));}
@GetMapping("/admin/customers") public List<Map<String,Object>> allCustomers(@RequestHeader(value="Authorization",required=false) String h){require(h,"admin");return service.customers().stream().map(this::customerDto).toList();}
@GetMapping("/admin/bills") public List<Map<String,Object>> allBills(@RequestHeader(value="Authorization",required=false) String h){require(h,"admin");return service.allBills().stream().map(this::billDto).toList();}
@PostMapping("/admin/tariff/calculate") public Map<String,Object> quote(@RequestHeader(value="Authorization",required=false) String h,@Valid @RequestBody TariffRequest r){require(h,"admin");TariffService.Quote q=service.calculate(r.tariffType(),r.units());return Map.of("unitsConsumed",q.unitsConsumed(),"energyCharge",q.energyCharge(),"fixedCharge",q.fixedCharge(),"totalAmount",q.totalAmount());}
@PostMapping("/admin/bills") public Map<String,Object> create(@RequestHeader(value="Authorization",required=false) String h,@Valid @RequestBody CreateBill r){require(h,"admin");return billDto(service.createBill(r.customerId(),r.billingMonth(),r.previousReading(),r.currentReading(),r.tariffType()));}
private Session require(String h,String role){if(h==null||!h.startsWith("Bearer "))throw PortalException.unauthorized("Please sign in again.");Session s=sessions.get(h.substring(7));if(s==null||!s.role.equals(role))throw PortalException.unauthorized("Session invalid. Please sign in again.");return s;}
private Map<String,Object> customerDto(Customer c){return Map.of("id",c.getId(),"customerId",c.getCustomerId(),"name",c.getName(),"mobile",c.getMobile(),"tariffType",c.getTariffType().name(),"active",c.isActive());}
private Map<String,Object> billDto(ElectricityBill b){return Map.ofEntries(Map.entry("id",b.getId()),Map.entry("billNumber",b.getBillNumber()),Map.entry("customerId",b.getCustomer().getCustomerId()),Map.entry("customerName",b.getCustomer().getName()),Map.entry("billingMonth",b.getBillingMonth()),Map.entry("previousReading",b.getPreviousReading()),Map.entry("currentReading",b.getCurrentReading()),Map.entry("unitsConsumed",b.getUnitsConsumed()),Map.entry("tariffType",b.getTariffType().name()),Map.entry("energyCharge",b.getEnergyCharge()),Map.entry("fixedCharge",b.getFixedCharge()),Map.entry("amount",b.getAmount()),Map.entry("status",b.getStatus().name()),Map.entry("createdAt",b.getCreatedAt().toString()));}
private record Session(String role,String subject){}
public record OtpRequest(@NotBlank String customerId,@NotBlank @Pattern(regexp="\\d{10}") String mobile){}
public record OtpVerify(@NotBlank String requestId,@NotBlank String customerId,@NotBlank @Pattern(regexp="\\d{10}") String mobile,@NotBlank @Pattern(regexp="\\d{6}") String otp){}
public record AdminLogin(@NotBlank String adminId,@NotBlank String password){}
public record TariffRequest(@NotNull TariffType tariffType,@NotNull @DecimalMin("0.0") BigDecimal units){}
public record CreateBill(@NotBlank String customerId,@NotBlank String billingMonth,@NotNull @DecimalMin("0.0") BigDecimal previousReading,@NotNull @DecimalMin("0.0") BigDecimal currentReading,@NotNull TariffType tariffType){}
public record PayRequest(String method){} public record NewCustomer(@NotBlank String customerId,@NotBlank String name,@NotBlank @Pattern(regexp="\\d{10}") String mobile,@NotNull TariffType tariffType){}
}